CREATE TABLE admins (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,username text NOT NULL,password_hash text NOT NULL,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,CONSTRAINT chk_admins_username CHECK (length(trim(username)) BETWEEN 1 AND 100));

CREATE TABLE provider_accounts (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,identity_key text NOT NULL,provider text NOT NULL,name text NOT NULL,email text,user_id text,team_id text,source_key text NOT NULL,enabled boolean NOT NULL,auth_status text NOT NULL,priority bigint NOT NULL DEFAULT 1,max_concurrent bigint NOT NULL DEFAULT 8,minimum_remaining double precision NOT NULL,failure_count bigint NOT NULL,cooldown_until timestamptz,last_error text,last_used_at timestamptz,observed_model text,observed_model_at timestamptz,build_api_fallback boolean NOT NULL DEFAULT false,build_route_mode text NOT NULL DEFAULT 'auto',build_super_entitled boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,CONSTRAINT chk_accounts_build_route_mode CHECK (build_route_mode IN ('auto','build','xai')),CONSTRAINT chk_accounts_minimum_remaining CHECK (minimum_remaining >= 0),CONSTRAINT chk_accounts_last_error CHECK (length(last_error) <= 512),CONSTRAINT chk_accounts_provider CHECK (provider IN ('grok_build','grok_web','grok_console')),CONSTRAINT chk_accounts_user_id CHECK (length(user_id) <= 255),CONSTRAINT chk_accounts_identity_key CHECK (length(identity_key) = 64),CONSTRAINT chk_accounts_max_concurrent CHECK (max_concurrent BETWEEN 1 AND 256),CONSTRAINT chk_accounts_name CHECK (length(trim(name)) BETWEEN 1 AND 160),CONSTRAINT chk_accounts_team_id CHECK (length(team_id) <= 255),CONSTRAINT chk_accounts_auth_status CHECK (auth_status IN ('active','reauthRequired')),CONSTRAINT chk_accounts_source_key CHECK (length(trim(source_key)) BETWEEN 1 AND 512),CONSTRAINT chk_accounts_failure_count CHECK (failure_count >= 0),CONSTRAINT chk_accounts_observed_model CHECK (length(observed_model) <= 255),CONSTRAINT chk_accounts_email CHECK (length(email) <= 255));

CREATE TABLE model_routes (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,public_id text NOT NULL,provider text NOT NULL,upstream_model text NOT NULL,capability text NOT NULL,origin text NOT NULL DEFAULT 'discovered',enabled boolean NOT NULL,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,CONSTRAINT chk_model_routes_capability CHECK (capability IN ('responses','chat','image','image_edit','video')),CONSTRAINT chk_model_routes_public_id CHECK (length(trim(public_id)) BETWEEN 1 AND 255),CONSTRAINT chk_model_routes_upstream_model CHECK (length(trim(upstream_model)) BETWEEN 1 AND 255),CONSTRAINT chk_model_routes_origin CHECK (origin IN ('catalog','discovered','manual')),CONSTRAINT chk_model_routes_provider CHECK (provider IN ('grok_build','grok_web','grok_console')));

CREATE TABLE client_keys (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name text NOT NULL,prefix text NOT NULL,secret_hash text NOT NULL,encrypted_secret text NOT NULL,enabled boolean NOT NULL,expires_at timestamptz,rpm_limit bigint NOT NULL DEFAULT 120,max_concurrent bigint NOT NULL DEFAULT 8,billing_limit_usd_ticks bigint NOT NULL DEFAULT 0,billed_usage_usd_ticks bigint NOT NULL DEFAULT 0,reserved_usage_usd_ticks bigint NOT NULL DEFAULT 0,last_used_at timestamptz,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,CONSTRAINT chk_client_keys_max_concurrent CHECK (max_concurrent BETWEEN 1 AND 1024),CONSTRAINT chk_client_keys_reserved_usage CHECK (reserved_usage_usd_ticks >= 0),CONSTRAINT chk_client_keys_name CHECK (length(trim(name)) BETWEEN 1 AND 160),CONSTRAINT chk_client_keys_prefix CHECK (length(prefix) BETWEEN 1 AND 32),CONSTRAINT chk_client_keys_encrypted_secret CHECK (length(trim(encrypted_secret)) BETWEEN 1 AND 4096),CONSTRAINT chk_client_keys_billing_limit CHECK (billing_limit_usd_ticks BETWEEN 0 AND 9000000000000000),CONSTRAINT chk_client_keys_rpm CHECK (rpm_limit BETWEEN 1 AND 100000),CONSTRAINT chk_client_keys_secret_hash CHECK (length(secret_hash) = 64),CONSTRAINT chk_client_keys_billed_usage CHECK (billed_usage_usd_ticks >= 0));

CREATE TABLE egress_nodes (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name text NOT NULL,scope text NOT NULL,enabled boolean NOT NULL DEFAULT true,encrypted_proxy_url text NOT NULL DEFAULT '',user_agent text NOT NULL DEFAULT '',encrypted_cloudflare_cookie text NOT NULL DEFAULT '',health double precision NOT NULL DEFAULT 1,failure_count bigint NOT NULL DEFAULT 0,cooldown_until timestamptz,last_error text,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,CONSTRAINT chk_egress_nodes_proxy_url CHECK (length(encrypted_proxy_url) <= 65536),CONSTRAINT chk_egress_nodes_health CHECK (health >= 0 AND health <= 1),CONSTRAINT chk_egress_nodes_user_agent CHECK (length(user_agent) <= 512),CONSTRAINT chk_egress_nodes_cf_cookie CHECK (length(encrypted_cloudflare_cookie) <= 65536),CONSTRAINT chk_egress_nodes_failures CHECK (failure_count >= 0),CONSTRAINT chk_egress_nodes_last_error CHECK (length(last_error) <= 512),CONSTRAINT chk_egress_nodes_name CHECK (length(trim(name)) BETWEEN 1 AND 160),CONSTRAINT chk_egress_nodes_specific_scope CHECK (scope IN ('grok_build','grok_web','grok_console','grok_web_asset')));

