CREATE TABLE account_credentials (account_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,auth_type text NOT NULL,client_id text,encrypted_primary text NOT NULL DEFAULT '',encrypted_refresh text NOT NULL DEFAULT '',encrypted_cloudflare_cookie text NOT NULL DEFAULT '',expires_at timestamptz,refresh_due_at timestamptz,last_refresh_at timestamptz,refresh_failures bigint NOT NULL DEFAULT 0,last_refresh_error text NOT NULL DEFAULT '',refresh_permanent boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL,CONSTRAINT fk_provider_accounts_credential FOREIGN KEY (account_id) REFERENCES provider_accounts(id) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT chk_account_credentials_refresh_failures CHECK (refresh_failures >= 0),CONSTRAINT chk_account_credentials_auth_type CHECK (auth_type IN ('oauth','sso')),CONSTRAINT chk_account_credentials_client_id CHECK (length(client_id) <= 255),CONSTRAINT chk_account_credentials_secret CHECK (((auth_type = 'oauth' AND (encrypted_primary <> '' OR encrypted_refresh <> '')) OR (auth_type = 'sso' AND encrypted_primary <> '' AND encrypted_refresh = '')) AND length(encrypted_primary) <= 65536 AND length(encrypted_refresh) <= 65536),CONSTRAINT chk_account_credentials_cf_cookie CHECK (length(encrypted_cloudflare_cookie) <= 65536),CONSTRAINT chk_account_credentials_refresh_error CHECK (length(last_refresh_error) <= 100));

CREATE TABLE account_provider_links (web_account_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,build_account_id bigint NOT NULL,created_at timestamptz NOT NULL,CONSTRAINT fk_account_provider_links_web_account FOREIGN KEY (web_account_id) REFERENCES provider_accounts(id) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT fk_account_provider_links_build_account FOREIGN KEY (build_account_id) REFERENCES provider_accounts(id) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT chk_account_provider_links_distinct CHECK (web_account_id <> build_account_id));

