CREATE TABLE request_audits (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,event_id text,request_id text NOT NULL,client_key_id bigint NOT NULL,client_key_name text,model_route_id bigint NOT NULL,model_public_id text,model_upstream_model text,provider text NOT NULL,operation text NOT NULL,usage_source text NOT NULL,account_id bigint,account_name text,egress_node_id bigint,egress_node_name text NOT NULL DEFAULT '',egress_scope text NOT NULL DEFAULT '',egress_mode text NOT NULL DEFAULT '',status_code bigint NOT NULL,streaming boolean NOT NULL DEFAULT false,media_input_images bigint NOT NULL DEFAULT 0,media_output_images bigint NOT NULL DEFAULT 0,media_output_seconds bigint NOT NULL DEFAULT 0,input_tokens bigint NOT NULL DEFAULT 0,cached_input_tokens bigint NOT NULL DEFAULT 0,output_tokens bigint NOT NULL DEFAULT 0,reasoning_tokens bigint NOT NULL DEFAULT 0,total_tokens bigint NOT NULL DEFAULT 0,cost_in_usd_ticks bigint NOT NULL DEFAULT 0,estimated_cost_in_usd_ticks bigint NOT NULL DEFAULT 0,pricing_model text,pricing_version text,num_sources_used bigint NOT NULL DEFAULT 0,num_server_side_tools_used bigint NOT NULL DEFAULT 0,context_input_tokens bigint NOT NULL DEFAULT 0,context_output_tokens bigint NOT NULL DEFAULT 0,duration_ms bigint NOT NULL DEFAULT 0,error_code text,attempt_count bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL,CONSTRAINT chk_request_audits_metrics CHECK (media_input_images >= 0 AND media_output_images >= 0 AND media_output_seconds >= 0 AND input_tokens >= 0 AND cached_input_tokens >= 0 AND output_tokens >= 0 AND reasoning_tokens >= 0 AND total_tokens >= 0 AND cost_in_usd_ticks >= 0 AND estimated_cost_in_usd_ticks >= 0 AND num_sources_used >= 0 AND num_server_side_tools_used >= 0 AND context_input_tokens >= 0 AND context_output_tokens >= 0 AND duration_ms >= 0),CONSTRAINT chk_request_audits_error_code CHECK (length(error_code) <= 100),CONSTRAINT chk_request_audits_client_key_name CHECK (length(client_key_name) <= 160),CONSTRAINT chk_request_audits_model_public_id CHECK (length(model_public_id) <= 255),CONSTRAINT chk_request_audits_operation CHECK (operation IN ('responses','compaction','chat','messages','image','image_edit','video')),CONSTRAINT chk_request_audits_egress_node_name CHECK (length(egress_node_name) <= 160),CONSTRAINT chk_request_audits_pricing_version CHECK (length(pricing_version) <= 20),CONSTRAINT chk_request_audits_provider CHECK (provider IN ('grok_build','grok_web','grok_console')),CONSTRAINT chk_request_audits_attempt_count CHECK (attempt_count >= 0),CONSTRAINT chk_request_audits_event_id CHECK (event_id = '' OR length(event_id) BETWEEN 16 AND 64),CONSTRAINT chk_request_audits_client_key_id CHECK (client_key_id > 0),CONSTRAINT chk_request_audits_egress_mode CHECK (egress_mode IN ('','direct','proxy')),CONSTRAINT chk_request_audits_status_code CHECK (status_code BETWEEN 100 AND 599),CONSTRAINT chk_request_audits_pricing_model CHECK (length(pricing_model) <= 100),CONSTRAINT chk_request_audits_request_id CHECK (length(request_id) BETWEEN 1 AND 64),CONSTRAINT chk_request_audits_model_upstream_model CHECK (length(model_upstream_model) <= 255),CONSTRAINT chk_request_audits_account_name CHECK (length(account_name) <= 160),CONSTRAINT chk_request_audits_egress_node_id CHECK (egress_node_id IS NULL OR egress_node_id > 0),CONSTRAINT chk_request_audits_model_route_id CHECK (model_route_id > 0),CONSTRAINT chk_request_audits_usage_source CHECK (usage_source IN ('upstream','estimated','none')),CONSTRAINT chk_request_audits_account_id CHECK (account_id IS NULL OR account_id > 0),CONSTRAINT chk_request_audits_egress_scope CHECK (egress_scope IN ('','grok_build','grok_web','grok_console','grok_web_asset')));

CREATE TABLE request_audit_attempts (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,audit_id bigint NOT NULL,number bigint NOT NULL,source text NOT NULL,stage text NOT NULL,account_id bigint,account_name text NOT NULL DEFAULT '',method text NOT NULL DEFAULT '',request_path text NOT NULL DEFAULT '',upstream_url text NOT NULL DEFAULT '',started_at timestamptz NOT NULL,duration_ms bigint NOT NULL DEFAULT 0,upstream_status_code bigint,upstream_status text NOT NULL DEFAULT '',response_headers_json text NOT NULL DEFAULT '{}',response_body bytea,response_body_truncated boolean NOT NULL DEFAULT false,transport_error text NOT NULL DEFAULT '',error_chain_json text NOT NULL DEFAULT '[]',CONSTRAINT fk_request_audit_attempts_audit FOREIGN KEY (audit_id) REFERENCES request_audits(id) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT chk_request_audit_attempts_account_name CHECK (length(account_name) <= 160),CONSTRAINT chk_request_audit_attempts_transport_error CHECK (length(transport_error) <= 2048),CONSTRAINT chk_request_audit_attempts_source CHECK (source IN ('upstream_http','gateway_transport','credential')),CONSTRAINT chk_request_audit_attempts_account_id CHECK (account_id IS NULL OR account_id > 0),CONSTRAINT chk_request_audit_attempts_error_chain CHECK (length(error_chain_json) <= 32768),CONSTRAINT chk_request_audit_attempts_upstream_url CHECK (length(upstream_url) <= 4096),CONSTRAINT chk_request_audit_attempts_status_text CHECK (length(upstream_status) <= 128),CONSTRAINT chk_request_audit_attempts_body CHECK (length(response_body) <= 65536),CONSTRAINT chk_request_audit_attempts_headers CHECK (length(response_headers_json) <= 32768),CONSTRAINT chk_request_audit_attempts_stage CHECK (length(trim(stage)) BETWEEN 1 AND 64),CONSTRAINT chk_request_audit_attempts_audit_id CHECK (audit_id > 0),CONSTRAINT chk_request_audit_attempts_method CHECK (length(method) <= 16),CONSTRAINT chk_request_audit_attempts_duration CHECK (duration_ms >= 0),CONSTRAINT chk_request_audit_attempts_status CHECK (upstream_status_code IS NULL OR upstream_status_code BETWEEN 100 AND 599),CONSTRAINT chk_request_audit_attempts_number CHECK (number > 0),CONSTRAINT chk_request_audit_attempts_request_path CHECK (length(request_path) <= 2048));

