CREATE TABLE web_response_states (response_id text,account_id bigint NOT NULL,conversation_id text NOT NULL,upstream_parent_response_id text NOT NULL,response_json text NOT NULL,status text NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,PRIMARY KEY (response_id),CONSTRAINT fk_web_response_states_account FOREIGN KEY (account_id) REFERENCES provider_accounts(id) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT chk_web_response_states_id CHECK (length(response_id) BETWEEN 1 AND 255),CONSTRAINT chk_web_response_states_account_id CHECK (account_id > 0),CONSTRAINT chk_web_response_states_parent CHECK (length(trim(upstream_parent_response_id)) BETWEEN 1 AND 255),CONSTRAINT chk_web_response_states_json CHECK (length(response_json) <= 16777216),CONSTRAINT chk_web_response_states_conversation CHECK (length(trim(conversation_id)) BETWEEN 1 AND 255),CONSTRAINT chk_web_response_states_status CHECK (status IN ('in_progress','completed','failed','cancelled')),CONSTRAINT chk_web_response_states_expiry CHECK (expires_at > created_at));

CREATE TABLE media_assets (id text,kind text NOT NULL,storage_key text NOT NULL,mime_type text NOT NULL,size_bytes bigint NOT NULL,sha256 text NOT NULL,created_at timestamptz NOT NULL,PRIMARY KEY (id),CONSTRAINT chk_media_assets_sha CHECK (length(sha256) = 64),CONSTRAINT chk_media_assets_id CHECK (length(trim(id)) BETWEEN 16 AND 64),CONSTRAINT chk_media_assets_mime CHECK (mime_type IN ('image/jpeg','image/png','image/webp','image/gif','video/mp4','video/webm','video/quicktime')),CONSTRAINT chk_media_assets_size CHECK (size_bytes > 0 AND size_bytes <= 268435456),CONSTRAINT chk_media_assets_kind CHECK (kind IN ('image','video')),CONSTRAINT chk_media_assets_storage_key CHECK (length(trim(storage_key)) BETWEEN 1 AND 512));

CREATE TABLE media_jobs (id text,request_id text NOT NULL,client_key_id bigint NOT NULL,client_key_name text NOT NULL DEFAULT '',account_id bigint NOT NULL,account_name text NOT NULL DEFAULT '',egress_node_id bigint,egress_node_name text NOT NULL DEFAULT '',egress_scope text NOT NULL DEFAULT '',egress_mode text NOT NULL DEFAULT '',provider text NOT NULL,model text NOT NULL,model_route_id bigint NOT NULL,upstream_model text NOT NULL,prompt text NOT NULL,seconds bigint NOT NULL,size text NOT NULL,quality text NOT NULL,status text NOT NULL,progress bigint NOT NULL,input_json text NOT NULL DEFAULT '{}',upstream_url text NOT NULL DEFAULT '',result_asset_id text NOT NULL DEFAULT '',content_type text NOT NULL DEFAULT '',error_code text NOT NULL DEFAULT '',error_message text NOT NULL DEFAULT '',lease_until timestamptz,claim_token text NOT NULL DEFAULT '',created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,completed_at timestamptz,usage_recorded_at timestamptz,PRIMARY KEY (id),CONSTRAINT fk_media_jobs_account FOREIGN KEY (account_id) REFERENCES provider_accounts(id) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT fk_media_jobs_client_key FOREIGN KEY (client_key_id) REFERENCES client_keys(id) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT chk_media_jobs_account_name CHECK (length(account_name) <= 160),CONSTRAINT chk_media_jobs_account_id CHECK (account_id > 0),CONSTRAINT chk_media_jobs_quality CHECK (length(trim(quality)) BETWEEN 1 AND 32),CONSTRAINT chk_media_jobs_seconds CHECK (seconds BETWEEN 1 AND 15),CONSTRAINT chk_media_jobs_claim_token CHECK (claim_token = '' OR length(claim_token) BETWEEN 16 AND 64),CONSTRAINT chk_media_jobs_size CHECK (length(trim(size)) BETWEEN 1 AND 32),CONSTRAINT chk_media_jobs_egress_node_id CHECK (egress_node_id IS NULL OR egress_node_id > 0),CONSTRAINT chk_media_jobs_progress CHECK (progress BETWEEN 0 AND 100),CONSTRAINT chk_media_jobs_model_route_id CHECK (model_route_id > 0),CONSTRAINT chk_media_jobs_error_code CHECK (length(error_code) <= 100),CONSTRAINT chk_media_jobs_error_message CHECK (length(error_message) <= 512),CONSTRAINT chk_media_jobs_result_asset_id CHECK (result_asset_id = '' OR length(trim(result_asset_id)) BETWEEN 16 AND 64),CONSTRAINT chk_media_jobs_client_key_name CHECK (length(client_key_name) <= 160),CONSTRAINT chk_media_jobs_input_json CHECK (length(input_json) <= 1048576),CONSTRAINT chk_media_jobs_content_type CHECK (length(content_type) <= 128),CONSTRAINT chk_media_jobs_model CHECK (length(trim(model)) BETWEEN 1 AND 255),CONSTRAINT chk_media_jobs_status CHECK (status IN ('queued','in_progress','completed','failed')),CONSTRAINT chk_media_jobs_client_key_id CHECK (client_key_id > 0),CONSTRAINT chk_media_jobs_egress_node_name CHECK (length(egress_node_name) <= 160),CONSTRAINT chk_media_jobs_provider CHECK (provider IN ('grok_web','grok_build')),CONSTRAINT chk_media_jobs_upstream_url CHECK (length(upstream_url) <= 8192),CONSTRAINT chk_media_jobs_upstream_model CHECK (length(trim(upstream_model)) BETWEEN 1 AND 255),CONSTRAINT chk_media_jobs_request_id CHECK (length(request_id) BETWEEN 1 AND 64),CONSTRAINT chk_media_jobs_egress_mode CHECK (egress_mode IN ('','direct','proxy')),CONSTRAINT chk_media_jobs_prompt CHECK (length(prompt) BETWEEN 0 AND 100000),CONSTRAINT chk_media_jobs_egress_scope CHECK (egress_scope IN ('','grok_web','grok_build')),CONSTRAINT chk_media_jobs_id CHECK (length(id) BETWEEN 1 AND 64));

CREATE TABLE media_upload_tickets (token_hash text,asset_id text NOT NULL,job_id text NOT NULL,max_bytes bigint NOT NULL,allowed_mime text NOT NULL DEFAULT 'video/mp4',expires_at timestamptz NOT NULL,consumed_at timestamptz,created_at timestamptz NOT NULL,PRIMARY KEY (token_hash),CONSTRAINT chk_media_upload_tickets_asset_id CHECK (length(trim(asset_id)) BETWEEN 16 AND 64),CONSTRAINT chk_media_upload_tickets_mime CHECK (length(trim(allowed_mime)) BETWEEN 1 AND 128),CONSTRAINT chk_media_upload_tickets_token_hash CHECK (length(token_hash) = 64),CONSTRAINT chk_media_upload_tickets_job_id CHECK (length(trim(job_id)) BETWEEN 1 AND 64),CONSTRAINT chk_media_upload_tickets_max_bytes CHECK (max_bytes > 0 AND max_bytes <= 268435456));

CREATE TABLE runtime_settings (key text,value_json text NOT NULL,revision bigint NOT NULL,updated_at timestamptz NOT NULL,PRIMARY KEY (key),CONSTRAINT chk_runtime_settings_json_length CHECK (length(value_json) <= 1048576),CONSTRAINT chk_runtime_settings_key CHECK (length(trim(key)) BETWEEN 1 AND 64));

