-- Preserve the existing Web SSO-derived egress identity without decrypting credentials.
UPDATE web_account_profiles AS profile
SET egress_identity = 'sso_' || lower(substr(account.source_key, 5, 32))
FROM provider_accounts AS account
WHERE account.id = profile.account_id
  AND account.provider = 'grok_web'
  AND profile.egress_identity = ''
  AND account.source_key ~ '^sso:[0-9A-Fa-f]{64}$';
